// Station 3: k-Means mit 342 Pinguinen
// Merkmale (normiert): x = Schnabellänge, y = Schnabeltiefe, z = Flossenlänge
// Lösung
Punkt[] pinguine = Datensatz.pinguine();
Merkmalsraum raum = new Merkmalsraum();
raum.zeige(pinguine);

KMeans km = new KMeans(pinguine, 3);
int[] start = {0, 200, 300};        // Aufgabe 4: andere Startpunkte ausprobieren
km.setStart(start);
raum.zeigeZentren(km.getZentren());
raum.warte(1500);

int durchgaenge = km.lauf(raum);
println("Fertig nach " + durchgaenge + " Durchgängen.");
println("Streuung: " + km.streuung());
Merkmalsraum.kreuztabelle(pinguine, 3);

