/**
 * Der k-Means-Algorithmus (Station 3).
 * zentren[c] enthält die Merkmalswerte des Zentrums von Cluster c.
 */
public class KMeans {
   private Punkt[] punkte;
   private double[][] zentren;
   private int k;

   public KMeans(Punkt[] punkte, int k) {
      this.punkte = punkte;
      this.k = k;
      zentren = new double[k][punkte[0].getAnzahlMerkmale()];
   }

   // Startzentren: Kopien der Punkte mit den angegebenen Nummern (fertig)
   public void setStart(int[] nummern) {
      for (int c = 0; c < k; c++) {
         for (int j = 0; j < zentren[c].length; j++) {
            zentren[c][j] = punkte[nummern[c]].getWert(j);
         }
      }
   }

   // Startzentren gleichmäßig über die Liste verteilt: Punkte 0, n/k, 2n/k, … (fertig)
   public void setStartVerteilt() {
      int[] nummern = new int[k];
      for (int c = 0; c < k; c++) {
         nummern[c] = c * (punkte.length / k);
      }
      setStart(nummern);
   }

   public double[][] getZentren() {
      return zentren;
   }

   // TODO 3a: Abstand zweier Merkmalsvektoren (Satz des Pythagoras, beliebig viele Merkmale)
   public double abstand(double[] a, double[] b) {
      double summe = 0;
      for (int j = 0; j < a.length; j++) {
         summe = summe + (a[j] - b[j]) * (a[j] - b[j]);
      }
      return Math.sqrt(summe);
   }

   // TODO 3b: ① Jeden Punkt dem nächsten Zentrum zuordnen.
   //          Rückgabe: true, wenn sich mindestens eine Zuordnung geändert hat.
   public boolean zuordnen() {
      boolean geaendert = false;
      for (int i = 0; i < punkte.length; i++) {
         int bester = 0;
         double kleinster = abstand(punkte[i].getWerte(), zentren[0]);
         for (int c = 1; c < k; c++) {
            double d = abstand(punkte[i].getWerte(), zentren[c]);
            if (d < kleinster) {
               kleinster = d;
               bester = c;
            }
         }
         if (punkte[i].getCluster() != bester) {
            punkte[i].setCluster(bester);
            geaendert = true;
         }
      }
      return geaendert;
   }

   // TODO 3c: ② Jedes Zentrum auf den Mittelwert seiner Punkte setzen.
   //          Ein Zentrum ohne Punkte bleibt, wo es ist.
   public void zentrenVerschieben() {
      for (int c = 0; c < k; c++) {
         double[] summe = new double[zentren[c].length];
         int anzahl = 0;
         for (int i = 0; i < punkte.length; i++) {
            if (punkte[i].getCluster() == c) {
               anzahl++;
               for (int j = 0; j < summe.length; j++) {
                  summe[j] = summe[j] + punkte[i].getWert(j);
               }
            }
         }
         if (anzahl > 0) {
            for (int j = 0; j < summe.length; j++) {
               zentren[c][j] = summe[j] / anzahl;
            }
         }
      }
   }

   // TODO 3d: ③ Wiederholen, solange sich beim Zuordnen etwas ändert.
   //          Rückgabe: Zahl der Durchgänge (raum == null: ohne Anzeige, für die Tests)
   public int lauf(Merkmalsraum raum) {
      int durchgaenge = 0;
      while (zuordnen()) {
         if (raum != null) {
            raum.faerbe(punkte);
            raum.warte(700);
         }
         zentrenVerschieben();
         if (raum != null) {
            raum.zeigeZentren(zentren);
            raum.warte(700);
         }
         durchgaenge++;
      }
      return durchgaenge;
   }

   // TODO 5: Streuung = Summe der quadrierten Abstände jedes Punkts zu seinem Zentrum
   public double streuung() {
      double summe = 0;
      for (int i = 0; i < punkte.length; i++) {
         double d = abstand(punkte[i].getWerte(), zentren[punkte[i].getCluster()]);
         summe = summe + d * d;
      }
      return summe;
   }
}

/**
 * Ein Datenpunkt im Merkmalsraum: seine Merkmalswerte (normiert auf 0 bis 1),
 * die wahre Art (nur zum Vergleichen, k-Means kennt sie nicht!) und die Nummer seines Clusters.
 * Muss nicht verändert werden.
 */
public class Punkt {
   private double[] werte;
   private String art;
   private int cluster;

   public Punkt(double[] werte, String art) {
      this.werte = werte;
      this.art = art;
      cluster = -1;            // -1: noch keinem Cluster zugeordnet
   }

   public double[] getWerte() {
      return werte;
   }

   public double getWert(int i) {
      return werte[i];
   }

   public int getAnzahlMerkmale() {
      return werte.length;
   }

   public String getArt() {
      return art;
   }

   public int getCluster() {
      return cluster;
   }

   public void setCluster(int cluster) {
      this.cluster = cluster;
   }
}

/**
 * Zeichnet Punkte und Zentren in einem drehbaren 3D-Würfel mit Kantenlänge 10.
 * Achsen: x (rot) = Schnabellänge, y (grün) = Schnabeltiefe, z (blau) = Flossenlänge, jeweils normiert.
 * Drehen: im Grafikfenster mit der Maus ziehen, zoomen: Mausrad.
 * Muss nicht verändert werden.
 */
public class Merkmalsraum {
   private World3d welt;
   private Sphere3d[] kugeln;
   private Box3d[] zentren;
   private int[] farben = {0x2563eb, 0xdc2626, 0x16a34a, 0xd97706, 0x9333ea, 0x0891b2, 0xdb2777, 0x65a30d};
   private double s = 10;

   public Merkmalsraum() {
      welt = new World3d();
      welt.setBackgroundColor(0xf8fafc);
      Box3d rahmen = new Box3d(s, s, s);
      rahmen.setMaterial(new BasicMaterial3d(0x94a3b8, true));
      rahmen.moveTo(s / 2, s / 2, s / 2);
      welt.getCamera().moveTo(s * 1.55, s * 1.15, s * 1.75);
      welt.getCamera().lookAt(s / 2, s / 2, s / 2, new Vector3(0, 1, 0), true);
      zentren = new Box3d[0];
   }

   private int farbe(int cluster) {
      if (cluster < 0) {
         return 0x94a3b8;
      }
      return farben[cluster % farben.length];
   }

   private int artFarbe(String art) {
      if (art.equals("Adelie")) {
         return 0xea580c;
      }
      if (art.equals("Zuegel")) {
         return 0x9333ea;
      }
      return 0x0e7490;
   }

   // Zeigt alle Punkte als kleine Kugeln (grau, solange sie keinem Cluster angehören).
   public void zeige(Punkt[] punkte) {
      kugeln = new Sphere3d[punkte.length];
      for (int i = 0; i < punkte.length; i++) {
         Sphere3d kugel = new Sphere3d(0.13, 8, 6);
         kugel.setMaterial(new LambertMaterial3d(farbe(punkte[i].getCluster())));
         kugel.moveTo(s * punkte[i].getWert(0), s * punkte[i].getWert(1), s * punkte[i].getWert(2));
         kugeln[i] = kugel;
      }
   }

   // Färbt jede Kugel in der Farbe ihres Clusters.
   public void faerbe(Punkt[] punkte) {
      for (int i = 0; i < punkte.length; i++) {
         kugeln[i].getMaterial().setColor(farbe(punkte[i].getCluster()));
      }
   }

   // Färbt jede Kugel nach der wahren Art: Adélie orange, Zügel violett, Esels petrol.
   public void faerbeNachArt(Punkt[] punkte) {
      for (int i = 0; i < punkte.length; i++) {
         kugeln[i].getMaterial().setColor(artFarbe(punkte[i].getArt()));
      }
   }

   // Zeigt die Zentren als Würfel in der Farbe ihres Clusters.
   public void zeigeZentren(double[][] z) {
      if (zentren.length != z.length) {
         for (int c = 0; c < zentren.length; c++) {
            zentren[c].destroy();
         }
         zentren = new Box3d[z.length];
         for (int c = 0; c < z.length; c++) {
            zentren[c] = new Box3d(0.5, 0.5, 0.5);
            zentren[c].setMaterial(new LambertMaterial3d(farbe(c)));
         }
      }
      for (int c = 0; c < z.length; c++) {
         zentren[c].moveTo(s * z[c][0], s * z[c][1], s * z[c][2]);
      }
   }

   public void warte(int millisekunden) {
      SystemTools.pause(millisekunden);
   }

   // Gibt aus, wie viele Pinguine jeder Art in jedem Cluster gelandet sind.
   public static void kreuztabelle(Punkt[] punkte, int k) {
      println("Cluster | Adelie | Zuegel | Esels");
      for (int c = 0; c < k; c++) {
         int a = 0;
         int z = 0;
         int e = 0;
         for (int i = 0; i < punkte.length; i++) {
            if (punkte[i].getCluster() == c) {
               if (punkte[i].getArt().equals("Adelie")) {
                  a++;
               } else if (punkte[i].getArt().equals("Zuegel")) {
                  z++;
               } else {
                  e++;
               }
            }
         }
         println("   " + c + "    |  " + rechts(a) + "   |  " + rechts(z) + "   |  " + rechts(e));
      }
   }

   private static String rechts(int zahl) {
      String t = "" + zahl;
      while (t.length() < 3) {
         t = " " + t;
      }
      return t;
   }
}

/**
 * Tests für KMeans. Starten: Klick auf das kleine Dreieck links neben "@Test"
 * oder auf den Knopf "Alle Tests starten" in der Leiste.
 */
public class KMeansTest {

   // vier Punkte in der Ebene: zwei links unten, zwei rechts oben
   private Punkt[] vierPunkte() {
      double[] a = {0, 0};
      double[] b = {1, 0};
      double[] c = {9, 9};
      double[] d = {10, 9};
      Punkt[] p = {new Punkt(a, "?"), new Punkt(b, "?"), new Punkt(c, "?"), new Punkt(d, "?")};
      return p;
   }

   private boolean fastGleich(double x, double y) {
      return Math.abs(x - y) < 0.000001;
   }

   @Test
   public void abstandBerechnen() {
      KMeans km = new KMeans(vierPunkte(), 2);
      double[] a = {1, 2};
      double[] b = {4, 6};
      double[] c = {0, 0, 0};
      double[] d = {1, 2, 2};
      Assertions.assertTrue(fastGleich(km.abstand(a, b), 5), "TODO 3a: Abstand von (1|2) und (4|6) muss 5 sein, ist " + km.abstand(a, b));
      Assertions.assertTrue(fastGleich(km.abstand(c, d), 3), "TODO 3a: Abstand von (0|0|0) und (1|2|2) muss 3 sein (drei Merkmale!), ist " + km.abstand(c, d));
      Assertions.assertTrue(fastGleich(km.abstand(a, a), 0), "TODO 3a: Abstand eines Punkts zu sich selbst muss 0 sein.");
   }

   @Test
   public void zuordnenNaechstesZentrum() {
      Punkt[] p = vierPunkte();
      KMeans km = new KMeans(p, 2);
      int[] start = {0, 3};
      km.setStart(start);
      Assertions.assertTrue(km.zuordnen(), "TODO 3b: Beim ersten Zuordnen ändert sich etwas, also muss zuordnen() true liefern.");
      Assertions.assertEquals(0, p[1].getCluster(), "TODO 3b: (1|0) liegt am nächsten bei Zentrum 0.");
      Assertions.assertEquals(1, p[2].getCluster(), "TODO 3b: (9|9) liegt am nächsten bei Zentrum 1.");
      Assertions.assertFalse(km.zuordnen(), "TODO 3b: Ein zweites Zuordnen ohne Verschieben ändert nichts, also false.");
   }

   @Test
   public void zentrenAufMittelwert() {
      Punkt[] p = vierPunkte();
      KMeans km = new KMeans(p, 2);
      int[] start = {0, 3};
      km.setStart(start);
      km.zuordnen();
      km.zentrenVerschieben();
      double[][] z = km.getZentren();
      Assertions.assertTrue(fastGleich(z[0][0], 0.5) && fastGleich(z[0][1], 0), "TODO 3c: Zentrum 0 muss in der Mitte von (0|0) und (1|0) liegen, also (0,5|0).");
      Assertions.assertTrue(fastGleich(z[1][0], 9.5) && fastGleich(z[1][1], 9), "TODO 3c: Zentrum 1 muss bei (9,5|9) liegen.");
   }

   @Test
   public void leeresClusterBleibtStehen() {
      Punkt[] p = vierPunkte();
      KMeans km = new KMeans(p, 2);
      int[] start = {0, 0};
      km.setStart(start);
      km.zuordnen();
      km.zentrenVerschieben();
      double[][] z = km.getZentren();
      Assertions.assertTrue(fastGleich(z[0][0], 5) && fastGleich(z[0][1], 4.5), "TODO 3c: Alle vier Punkte gehören zu Zentrum 0, es muss in ihre Mitte (5|4,5) wandern.");
      Assertions.assertTrue(fastGleich(z[1][0], 0) && fastGleich(z[1][1], 0), "TODO 3c: Ein Zentrum ohne Punkte bleibt, wo es ist (sonst Division durch 0).");
   }

   @Test
   public void laufBisNichtsMehrAendert() {
      Punkt[] p = vierPunkte();
      KMeans km = new KMeans(p, 2);
      int[] start = {0, 1};
      km.setStart(start);
      int n = km.lauf(null);
      Assertions.assertTrue(n >= 2, "TODO 3d: Mit den Startpunkten (0|0) und (1|0) braucht k-Means mehrere Durchgänge, gemeldet: " + n);
      Assertions.assertEquals(p[0].getCluster(), p[1].getCluster(), "TODO 3d: Am Ende gehören (0|0) und (1|0) zusammen.");
      Assertions.assertEquals(p[2].getCluster(), p[3].getCluster(), "TODO 3d: Am Ende gehören (9|9) und (10|9) zusammen.");
      Assertions.assertTrue(p[0].getCluster() != p[2].getCluster(), "TODO 3d: Die beiden Paare gehören in verschiedene Cluster.");
   }

   @Test
   public void streuungBerechnen() {
      Punkt[] p = vierPunkte();
      KMeans km = new KMeans(p, 2);
      int[] start = {0, 3};
      km.setStart(start);
      km.lauf(null);
      Assertions.assertTrue(fastGleich(km.streuung(), 1), "TODO 5: Streuung muss 4 · 0,5² = 1 sein, ist " + km.streuung());
   }
}
